before:
// One shared, actor-bound before/after snapshot for the whole fleet.
// Identity reads use the existing protected interface, never IP identity.
const bounded=CosProductTcpDisabledStage.cancellableIo(cosProductRequestStartedAt+26_000,Date.now,request.signal);
const io=cosProductSourceContext(context);
const reader=CosProductTcpDisabledStage.createProtectedSourceReader({...io,
  platformRpc:(name,signal)=>stageRead(name==='cos_mhelp_placement_snapshot'?'mhelp_census':'endpoint_evaluation',async()=>{const value=await io.platformRpc(name,signal);if(name==='cos_mhelp_placement_snapshot'){void value.upload;}return value;}),
  legacyRead:(path,signal)=>stageRead('saved_endpoints',()=>io.legacyRead(path,signal)),
  tracker:(candidate,sha,signal)=>stageRead('tracker_census',()=>io.tracker(candidate,sha,signal)),
});
diagnostic={stage:'endpoint_evaluation',code:'source_unavailable'};
const [fullSource,checks]=await bounded.request(signal=>Promise.all([
  reader(signal),
  stageRead('saved_checks',()=>legacyAll('camera_health_current?select=camera_device_id,port_status&order=camera_device_id.asc',context.headers,signal)),
]),26_000);
const source=await bounded.request(()=>CosProductTcpDisabledStage.productResourceMembership(fullSource),26_000);
const tracker=fullSource.tracker,deviceRows=fullSource.identitySources.devices;
diagnostic={stage:'endpoint_evaluation',code:'source_unavailable'};
const byId=new Map(checks.map(row=>[String(row.camera_device_id),row]));
if(byId.size!==checks.length)fail16('Saved endpoint checks have conflicting identities.',503);
const endpoints=deviceRows.map(device=>({
  deviceId:device.id,publicIp:device.public_ip,expectedPorts:device.expected_ports,
  connectionRevision:device.connection_revision,monitoringEnabled:device.monitoring_enabled,activationState:device.activation_state,
  portStatus:byId.get(String(device.id))?.port_status||null,
}));
const evaluated=CosProductTcpDisabledStage.buildTrackerIpReachability(source.census,tracker,endpoints,Date.now());

after:
// Read the same persisted evidence as Verify now. Provider identity,
// addresses and resource membership do not gate TCP reachability.
const bounded=CosProductTcpDisabledStage.cancellableIo(cosProductRequestStartedAt+26_000,Date.now,request.signal);
const io=cosProductSourceContext(context);
// The optional identity/endpoint adapter retains its original reader.
// It is not opened by the default saved-connection path.
const reader=signal=>CosProductTcpDisabledStage.createProtectedSourceReader(io)(signal);
const source=await bounded.request(signal=>readProductCheckSource({
  receipt:s=>io.platformRpc('cos_mhelp_placement_snapshot',s),
  census:CosProductTcpDisabledStage.currentMhelpProductConnectionCensus,
  tracker:(candidate,sha,s)=>io.tracker(candidate,sha,s),
  devices:s=>legacyAll('camera_devices?select=id,unit_key,public_ip,expected_ports,connection_revision,monitoring_enabled,activation_state&order=id.asc',context.headers,s),
  checks:s=>legacyAll('camera_health_current?select=camera_device_id,port_status&order=camera_device_id.asc',context.headers,s)
},signal),26_000);
const evaluated=CosProductTcpDisabledStage.buildTrackerIpReachability(source.census,source.tracker,source.endpoints,Date.now());
